def triangular(n):
    return n * (n + 1) // 2

def is_square(num):
    if num < 0:
        return False
    sqrt_n = int(num**0.5)
    return sqrt_n * sqrt_n == num

# Check small values of n
test_n = range(1, 15)
results = {}
for n in test_n:
    Sn = triangular(n)
    results[n] = (Sn, is_square(Sn))

print("n | S_n | Is S_n Square?")
for n, (Sn, is_sq) in results.items():
    print(f"{n:2} | {Sn:3} | {is_sq}")

